#ifndef HASHLOG_THREAD_H
#define HASHLOG_THREAD_H

#include <string.h>

#include <hashlog/exceptions.h>
#include <hashlog/core/refs.h>
#include <hashlog/core/config.h>

#define THREAD_FOLDER "threads"

typedef struct {
    /** head commit associated with the thread */
    char head_commit[HASH_HEX_SIZE];
    char root_commit[HASH_HEX_SIZE];
} thread_info_t;

/**
 * @brief Creates a new thread based on an existing commit.
 * 
 * @param commit_hex Pointer to the hash of the reference commit.
 * @param hex Output buffer to store the hash generated by the thread.
 */
int create_thread(thread_info_t* thread_info);

/**
 * @brief Analyzes the content of a thread and populates the output structure.
 * 
 * @param content Raw content of the thread to be analyzed.
 * @param out A pointer to the `thread_info_t` structure where the data will be stored.
 */
void parse_thread(char* content, thread_info_t* out);

#endif